const b = $json.body || $json;
// Delhivery push: { Shipment: { AWB, Status: { Status, StatusType, Instructions }, ReferenceNo, NSLCode } }
const dl = b.Shipment || b.shipment;
let e;
if (dl) {
  e = { provider: 'delhivery', awb: String(dl.AWB || dl.awb || ''), order_id: dl.ReferenceNo || '',
    status: `${dl.Status?.Status || ''} ${dl.Status?.StatusType || ''}`, reason_raw: dl.Status?.Instructions || dl.NSLCode || '',
    attempt: Number(dl.Status?.Attempts || dl.attempts || 1) };
} else {
  // Shiprocket tracking webhook
  const last = (b.scans || []).slice(-1)[0] || {};
  e = { provider: 'shiprocket', awb: String(b.awb || b.awb_code || ''), order_id: String(b.order_id || b.sr_order_id || ''),
    status: String(b.current_status || b.shipment_status || ''), reason_raw: b.ndr_reason || last.activity || last['sr-status-label'] || b.current_status || '',
    attempt: Number(b.ndr_attempts || b.attempts || 1) };
}
const isNdr = /undeliver|ndr|not delivered|delivery failed|failed attempt|consignee|refus|address|unavailable|door locked|premises closed|cod amount/i.test(`${e.status} ${e.reason_raw}`)
  && !/^delivered$/i.test(e.status.trim());
return isNdr && e.awb ? [{ json: { ...e, received_at: new Date().toISOString() } }] : [];

const e = $('Normalize Courier Event').first().json;
const s = $('Look Up Shipment').first()?.json || {};
const ndr_id = `${e.awb}-A${e.attempt}`;
if ($input.all().some(i => i.json.ndr_id === ndr_id)) return [];          // already handled this attempt
const r = `${e.reason_raw} ${e.status}`.toLowerCase();
const reason = /refus|reject|not interested|cancel/.test(r) ? 'refused'
  : /cod|cash|amount not ready|payment/.test(r) ? 'cod_not_ready'
  : /address|incomplete|wrong|landmark|not found|untraceable/.test(r) ? 'address_issue'
  : /closed|locked|holiday|office closed/.test(r) ? 'premises_closed'
  : /oda|out of delivery|serviceab/.test(r) ? 'out_of_area'
  : /unavailable|not available|not reachable|no response|phone|switched off|customer not/.test(r) ? 'customer_unavailable' : 'other';
const cod = /cod|cash/i.test(s.payment_mode || '');
const codAmt = Number(s.cod_amount) || 0;
let risk = { refused: 40, cod_not_ready: 25, address_issue: 20, customer_unavailable: 15, premises_closed: 10, out_of_area: 30, other: 15 }[reason]
  + (cod ? 20 : 0) + (e.attempt >= 2 ? 15 : 0) + (codAmt > 2000 ? 10 : 0);
risk = Math.min(100, risk);
const reasonText = { refused: 'the delivery was marked as refused', cod_not_ready: 'the cash-on-delivery amount was not ready',
  address_issue: 'the courier could not find the address', premises_closed: 'the premises were closed',
  out_of_area: 'the address is outside the courier\'s regular route', customer_unavailable: 'the courier could not reach you', other: 'the delivery could not be completed' }[reason];
const first = String(s.customer_name || 'there').split(' ')[0];
const token = Math.random().toString(36).slice(2, 10);
const msg = `Hi ${first} 👋 Your order *#${e.order_id || s.order_id}* (${s.items || 'your package'}) could not be delivered today because ${reasonText}.\n\n` +
  `Reply with a number:\n1️⃣ Deliver again tomorrow\n2️⃣ Choose another date (e.g. "Friday" / "after 3 days")\n3️⃣ Update the address or landmark (send the full address with pincode)\n4️⃣ Cancel the order\n\n` +
  `${cod ? `Please keep ₹${codAmt} ready for cash on delivery. ` : ''}Please reply within *24 hours* so the courier can re-attempt. 🙏`;
return [{ json: { ndr_id, ...e, order_id: e.order_id || s.order_id || '', provider: (s.provider || e.provider).toLowerCase(),
  customer_name: s.customer_name || '', phone: String(s.phone || '').replace(/\D/g, ''), address: s.address || '', pincode: s.pincode || '',
  payment_mode: cod ? 'COD' : 'Prepaid', cod_amount: codAmt, items: s.items || '', reason_code: reason, rto_risk: risk,
  risk_tier: risk >= 60 ? 'High' : risk >= 35 ? 'Medium' : 'Low', wa_message: msg, token, known_shipment: !!s.awb } }];

