for (const { json: j } of $input.all()) {
  const v = j.value || j.entry?.[0]?.changes?.[0]?.value || j;
  const m = (v.messages || [])[0]; if (!m) continue;
  const text = m.text?.body || m.button?.text || m.interactive?.button_reply?.title || m.location?.address || '';
  const loc = m.location ? `${m.location.name || ''} ${m.location.address || ''} (${m.location.latitude},${m.location.longitude})` : '';
  if (!text && !loc) continue;
  return [{ json: { phone: String(m.from).replace(/\D/g, ''), text: (text || loc).slice(0, 800), location: loc } }];
}
return [];

const r = $('Parse Customer Reply').first().json;
const open = $input.all().map(i => i.json).filter(c => c.ndr_id && /awaiting_customer|clarify|whatsapp_failed|escalated/.test(c.status || ''))
  .sort((a, b) => String(b.created_at).localeCompare(String(a.created_at)));
if (!open.length) return [];                                  // not an NDR conversation – ignore
return [{ json: { ...open[0], reply: r.text, reply_location: r.location, today: $now.setZone('Asia/Kolkata').toFormat('yyyy-LL-dd cccc') } }];

const c = $('Pick Latest Open Case').first().json;
const ai = $input.first().json.message?.content || {};
const today = $now.setZone('Asia/Kolkata').startOf('day');
const tries = Number(c.tries || 0);
let route = 'courier', problem = '';
let intent = ai.intent || 'unclear';
let date = intent === 'reattempt' ? today.plus({ days: 1 }).toISODate() : ai.date;
if (['reattempt', 'reschedule'].includes(intent)) {
  const d = date ? DateTime.fromISO(date, { zone: 'Asia/Kolkata' }) : null;
  const diff = d ? Math.round(d.diff(today, 'days').days) : null;
  if (!d || diff < 1 || diff > 5) { problem = 'The courier can only re-attempt within the next 1–5 days. Please choose a date in that range.'; route = 'clarify'; }
}
if (intent === 'update_address' && !/^\d{6}$/.test(String(ai.address?.pincode || ''))) { problem = 'Please send the full address including the 6-digit pincode.'; route = 'clarify'; }
if (intent === 'update_address' && ai.address?.pincode && String(ai.address.pincode) !== String(c.pincode)) {
  route = 'ops'; problem = `The customer wants a different pincode (${ai.address.pincode} vs ${c.pincode}). This needs a manual reroute or reship.`; }
if (intent === 'unclear' || (ai.confidence ?? 0) < 0.6) route = 'clarify';
if (route === 'clarify' && tries >= 2) route = 'ops';
if (intent === 'cancel' && c.provider === 'delhivery') route = 'ops';      // RTO via panel or ops
const addr = ai.address || {};
const fullAddr = [addr.line1, addr.line2, addr.landmark && `Landmark: ${addr.landmark}`, addr.city, addr.pincode].filter(Boolean).join(', ');
const note = intent === 'reschedule' ? `Customer requested delivery on ${date}${ai.time_window ? ' ' + ai.time_window : ''}`
  : intent === 'update_address' ? `Updated address: ${fullAddr}` : intent === 'alternate_phone' ? `Alternate phone: ${ai.alternate_phone}` : `Customer requested re-attempt on ${date}`;
// Shiprocket NDR action
const sr_body = { action: intent === 'cancel' ? 'return' : 're-attempt', comments: note.slice(0, 250),
  ...(intent === 'update_address' ? { address1: addr.line1 || '', address2: [addr.line2, addr.landmark].filter(Boolean).join(', ') } : {}),
  ...(intent === 'alternate_phone' ? { phone: String(ai.alternate_phone || '').replace(/\D/g, '').slice(-10) } : {}),
  ...(['reschedule', 'reattempt'].includes(intent) ? { deferred_date: date } : {}) };
// Delhivery NDR update API
const act = intent === 'reschedule' ? 'DEFER_DLV' : intent === 'update_address' || intent === 'alternate_phone' ? 'EDIT_DETAILS' : 'RE-ATTEMPT';
const dl_body = { data: [{ waybill: c.awb, act, ...(act === 'DEFER_DLV' ? { action_data: { deferred_date: date } } : {}),
  ...(act === 'EDIT_DETAILS' ? { action_data: { ...(fullAddr ? { add: fullAddr } : {}), ...(ai.alternate_phone ? { phone: String(ai.alternate_phone).replace(/\D/g, '').slice(-10) } : {}) } } : {}) }] };
return [{ json: { ...c, intent, action_date: date || '', new_address: fullAddr, time_window: ai.time_window || '', route, problem,
  reply_to_customer: route === 'clarify' && problem ? problem : (ai.reply_to_customer || ''), sr_body, dl_body, courier_note: note } }];

