const c = $('Build Courier Action').first().json;
const r = $input.first().json;
const body = typeof r.body === 'string' ? (() => { try { return JSON.parse(r.body); } catch (e) { return { raw: r.body }; } })() : (r.body || {});
const ok = r.statusCode >= 200 && r.statusCode < 300 && body.status !== false && !/error|fail|invalid/i.test(JSON.stringify(body.message || body.error || ''));
return [{ json: { ...c, courier_ok: ok, courier_status: r.statusCode, courier_response: JSON.stringify(body).slice(0, 400),
  courier_problem: ok ? '' : `Courier API rejected the action (HTTP ${r.statusCode}): ${JSON.stringify(body).slice(0, 200)}` } }];

