const REMIND_H = 6, ESCALATE_H = 20;
return $input.all().map(i => i.json).filter(c => c.ndr_id && c.created_at).flatMap(c => {
  const age = (Date.now() - new Date(c.created_at).getTime()) / 3600000;
  if (age >= ESCALATE_H) return [{ json: { ...c, sla: 'escalate', age_h: Math.round(age) } }];
  if (age >= REMIND_H && !c.reminded_at) return [{ json: { ...c, sla: 'remind', age_h: Math.round(age) } }];
  return [];
});
